// Facebook + Instagram webhook-оос ирсэн мессеж/postback задлах.
// FB:  body.object === 'page',       entry[].messaging[]
// IG:  body.object === 'instagram',  entry[].messaging[] (адил бүтэц)
// Платформ ялгаж platform талбар нэмнэ ('facebook' | 'instagram').
// → Build Messages нь platform-аас хамаарч IG-д текст, FB-д карт илгээнэ.

const body = $input.first().json.body;
// DEDUP — FB нэг мессежийг 2 удаа (retry) илгээдэг. mid-ийг static data-д санаж давхрыг алгасна.
var _sd = $getWorkflowStaticData('global');
_sd.seenMids = _sd.seenMids || [];
function _dup(mid){ if(!mid)return false; if(_sd.seenMids.indexOf(mid)!==-1)return true; _sd.seenMids.push(mid); if(_sd.seenMids.length>200)_sd.seenMids=_sd.seenMids.slice(-200); return false; }
// SKIP_COMMENT: comment event (changes) Messenger Parse-руу орохгүй (зөвхөн comment branch)
{ const e0=(body&&body.entry&&body.entry[0])||{}; if(e0.changes && !e0.messaging) return []; }
try{ const e0=(body&&body.entry&&body.entry[0])||{}; const m0=(e0.messaging&&e0.messaging[0])||{}; console.log('FBWH_DEBUG object='+(body&&body.object)+' recipient='+(m0.recipient&&m0.recipient.id)+' sender='+(m0.sender&&m0.sender.id)); }catch(e){}
if (!body) return [];

let platform = '';
if (body.object === 'page') platform = 'facebook';
else if (body.object === 'instagram') platform = 'instagram';
else return [];

// Get Started болон Ice Breaker payload-уудыг текст асуулт болгон хөрвүүлнэ
const PAYLOAD_TO_TEXT = {
  GET_STARTED: '__GET_STARTED__',
  IB_PROJECTS: 'бэлэн төсөл',
  IB_BOOKS: 'ном',
  IB_PRICING: 'үнэ төлбөрийн мэдээлэл',
  IB_DOWNLOAD: 'татаж авах заавар',
};

const out = [];
for (const entry of (body.entry || [])) {
  for (const msg of (entry.messaging || [])) {
    const psid = String(msg.sender && msg.sender.id || '');
    if (!psid) continue;

    // 1) Postback (Get Started, Ice Breaker) — FB дээр л байна
    if (msg.postback && msg.postback.payload) {
      const mapped = PAYLOAD_TO_TEXT[msg.postback.payload];
      const text = mapped || String(msg.postback.title || msg.postback.payload).trim();
      out.push({ json: { psid, text, isPostback: true, platform } });
      continue;
    }

    // 2) Энгийн текст мессеж (echo, attachment, story_mention алгасна)
    if (msg.message && msg.message.mid && _dup(msg.message.mid)) continue;
    if (msg.message && !msg.message.is_echo && msg.message.text) {
      out.push({ json: { psid, text: String(msg.message.text).trim(), isPostback: false, platform } });
    }
  }
}
return out;

// Prep Context — AI Agent-аас ӨМНӨ ажиллана. Pre-search БАЙХГҮЙ.
// Зөвхөн psid, userText, firstName бэлдэж AI-д өгөх agentInput угсарна.
// AI өөрөө өгүүлбэрийг ойлгож [SEARCH:keyword] гаргана (хайлтыг дараа нь хийнэ).
const NL = String.fromCharCode(10);
const psid = $('Parse').first().json.psid;
const userText = $('Parse').first().json.text;
const platform = $('Parse').first().json.platform || 'facebook';
const _conv = $('Get User Profile').first().json || {};
// /me/conversations?user_id=PSID → participants дотроос Page БИШ хэрэглэгчийн нэр
let _fbName = '';
try {
  const parts = ((_conv.data && _conv.data[0] && _conv.data[0].participants && _conv.data[0].participants.data) || []);
  const u = parts.find(function(p){ return p && p.id && p.id !== '1052275041465153'; });
  if (u && u.name) _fbName = String(u.name).trim();
} catch (e) { _fbName = ''; }
const profile = { first_name: _fbName, profile_pic: '' };
const firstName = (profile.first_name || '').trim();
  const profilePic = (profile.profile_pic || '').trim();
const isGetStarted = (userText === '__GET_STARTED__');
const nameLine = firstName ? ('Хэрэглэгчийн нэр: ' + firstName) : '';

// ⚠️ Холбоо барих контекстийг ЗӨВХӨН холбоо барих/бидний тухай асуулт илэрсэн
// үед л агентад оруулна. Үргэлж оруулбал том текст AI-ийн фокусыг сарниулж,
// "free", бүтээгдэхүүн хайх зэрэг бусад асуултад буруу (линк зохиосон) хариулдаг.
const lower = (userText || '').toLowerCase();
const contactTriggers = [
  'утас', 'дугаар', 'хаяг', 'холбоо', 'холбогд', 'имэйл', 'мэйл', 'и-мэйл',
  'хаана байр', 'байршил', 'хаяг', 'ажлын цаг', 'цагаар', 'социал', 'фэйсбүүк',
  'facebook', 'instagram', 'инстаграм', 'бидний тухай', 'танай тухай', 'хэн бэ',
  'хаягтай', 'утастай', 'phone', 'contact', 'address',
];
const needsContact = contactTriggers.some((t) => lower.includes(t));

// AI зөрүүдэлдэг тул холбоо барих асуултад AI-г ТОЙРЧ deterministic хариу
// (directReply) бэлдэнэ — Build Messages node үүнийг шууд reply болгоно.
let directReply = '';
if (needsContact) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.digitalger.mn/api/contact/chatbot-context',
      json: true,
      timeout: 4000,
    });
    const ct = String((resp && resp.contactText) || '').replace(/\s+/g, ' ');
    const email = (resp && resp.supportEmail) || 'info@digitalger.mn';
    const phoneM = ct.match(/\+?\d[\d\s\-]{6,}\d/);
    const phone = phoneM ? phoneM[0].trim() : '';
    const addrM = ct.match(/Хаяг[:\s]*([^•]+)/);
    const addr = addrM ? addrM[1].trim() : '';
    const socs = (resp && Array.isArray(resp.socials)) ? resp.socials : [];
    const parts = ['📞 Холбоо барих мэдээлэл:'];
    if (phone) parts.push('Утас: ' + phone);
    parts.push('Имэйл: ' + email);
    if (addr) parts.push('Хаяг: ' + addr);
    if (socs.length) parts.push(socs.join(NL));
    parts.push('Дэлгэрэнгүй: https://digitalger.mn/contact');
    directReply = parts.join(NL);
  } catch (e) {
    directReply = '';
  }
}

let agentInput;
if (isGetStarted) {
  agentInput = [nameLine, '=== ОНЦГОЙ: хэрэглэгч анх удаа орж ирлээ. Дулаан угтах мэндчилгээ бич, DigitalGer-ийг товч танилцуул. Бүтээгдэхүүн хайхгүй. ==='].filter(Boolean).join(NL);
} else {
  agentInput = [nameLine, '=== ХЭРЭГЛЭГЧИЙН МЕССЕЖ ===', userText].filter(Boolean).join(NL);
}
return [{ json: { psid, userText, firstName, profilePic, agentInput, isGetStarted, platform, directReply } }];

// Extract Keyword — AI Agent-ийн хариунаас [SEARCH:keyword] салгана.
// keyword байвал → дараагийн HTTP node backend-ийг ЦЭВЭР keyword-оор дуудна.
// [SEARCH:...] тэмдгийг хэрэглэгчид харагдах текстээс арилгана.
const prep = $('Prep Context').first().json;
const psid = prep.psid;
const platform = prep.platform || 'facebook';
let raw = ($input.first().json.output || '').trim();
// [SEARCH:xxx] эсвэл [SEARCH: xxx] хайх (кирилл/латин/зай хүлээнэ)
let keyword = '';
const m = raw.match(/\[SEARCH:\s*([^\]]*)\]/i);
if (m) {
  keyword = (m[1] || '').trim();
}
// Тэмдгийг текстээс бүрэн арилгана (хэд ч байж болно)
let replyText = raw.replace(/\[SEARCH:[^\]]*\]/ig, '').trim();
// Markdown цэвэрлэх: [текст](url) → "текст url", ** __ устгах
function stripMd(s){ s=String(s||''); var r='',i=0; while(i<s.length){ if(s[i]==='['){ var c=s.indexOf('](',i); if(c!==-1){ var e=s.indexOf(')',c+2); if(e!==-1){ var t=s.slice(i+1,c).trim(); var u=s.slice(c+2,e).trim(); r+=(t===u||!t)?u:(t+' '+u); i=e+1; continue; } } } r+=s[i]; i++; } r=r.split('**').join('').split('__').join(''); var parts=r.split(' '); var out=[]; for(var k=0;k<parts.length;k++){ if(k>0 && parts[k]!=='' && parts[k]===parts[k-1]){ continue; } out.push(parts[k]); } r=out.join(' '); return r.trim(); }
replyText = stripMd(replyText);

// ⚠️ FAQ ХАМГААЛАЛТ: AI андуурч ерөнхий FAQ/үйл үгийг [SEARCH:]-д тавьсан бол
// хайлт ХИЙХГҮЙ (AI-гийн текст хариуг шууд илгээнэ). Энэ нь "татаж авах яаж"
// гэх ерөнхий асуулт буруугаар бүтээгдэхүүн хайж "олдсонгүй" гэхээс сэргийлнэ.
const kwLc = keyword.toLowerCase().replace(/\s+/g, ' ').trim();
const FAQ_STOP = ['татаж авах','татах','худалдан авах','худалдаж авах','авах заавар','төлбөр','тулбур','qpay','купон','буцаалт','буцаан','формат','эрх','хэрхэн','яаж','хэрэглэх','ашиглах','нэвтрэх','бүртгэл','бүртгүүлэх','нууц үг','имэйл','видео хичээл үзэх','хичээл үзэх','үзэх заавар','тусламж','холбоо барих','админ','хэдэн төхөөрөмж','интернэт','офлайн','хэр удаан','хэдэн удаа','хямдрал','үнэ төлбөр'];
let isFaqLike = false;
for (let i = 0; i < FAQ_STOP.length; i++) { if (kwLc === FAQ_STOP[i]) { isFaqLike = true; break; } }
if (isFaqLike) {
  keyword = '';
}

const doSearch = keyword.length >= 2;
if (!replyText) replyText = doSearch ? 'Танд тохирох бүтээгдэхүүн хайж байна...' : 'Уучлаарай, дахин бичнэ үү.';
return [{ json: { psid, keyword, doSearch, replyText, platform } }];

// Build Messages — Extract Keyword-ийн replyText + Search by Keyword-ийн products
// ашиглаж текст + carousel карт угсарна.
//  - facebook  → текст + carousel карт
//  - instagram → текст + carousel карт ОРОЛДОНО (IG Messaging generic template
//    дэмждэг). Хэрэв Send Cards алдвал текст аль хэдийн явсан тул хэрэглэгч
//    хариу авна (текст fallback). Платформ хоёуланд карт бэлдэнэ.
const NL = String.fromCharCode(10);
const TUG = String.fromCharCode(0x20AE);
const ex = $('Extract Keyword').first().json;
const psid = ex.psid;
// ⚠️ platform-ийг Parse-ээс ШУУД (Extract Keyword/AI гинжээр алдагддаг тул IG→facebook болж байв)
let platform = ex.platform;
if (platform !== 'instagram' && platform !== 'facebook') {
  try { platform = $('Parse').first().json.platform; } catch (e) {}
}
if (platform !== 'instagram' && platform !== 'facebook') platform = 'facebook';
// Холбоо барих асуулт — Prep node-ийн deterministic directReply (бодит утас/хаяг/
// имэйл)-ийг AI хариунаас ДЭЭГҮҮР ашиглана (AI зохиодог тул найдвартай).
let _directReply = '';
try { _directReply = ($('Prep Context').first().json.directReply || '').trim(); } catch (e) { _directReply = ''; }
let replyText = _directReply || (ex.replyText || '').trim();
let search = {};
try { search = $('Search by Keyword').first().json || {}; } catch (e) { search = {}; }
const triedSearch = ex.doSearch === true;
const products = (triedSearch && Array.isArray(search.products)) ? search.products : [];
const showProducts = products.length > 0;

// Хайлт хийсэн ХАРИН бүтээгдэхүүн ОЛДООГҮЙ үед олдсонгүй мессежээр СОЛИНО.
if (triedSearch && !showProducts) {
  const kw = (ex.keyword || '').trim();
  const kwPart = kw ? ('"' + kw + '"-тэй холбоотой ') : '';
  replyText =
    kwPart + 'бүтээгдэхүүн одоогоор бэлэн алга байна 🙏' + NL +
    'Та өөр түлхүүр үгээр хайж үзэх үү? Эсвэл бүх бүтээгдэхүүнийг эндээс үзээрэй: https://digitalger.mn/products';
}

if (replyText.length > 1900) replyText = replyText.slice(0, 1897) + '...';

// ── Chat хадгалах: _ingest объект буцаана (task-runner bug → native HTTP node) ──
const _prep2 = $('Prep Context').first().json || {};
const _ingest = {
  channel: (platform === 'instagram') ? 'instagram' : 'facebook',
  sessionId: String(psid || '').slice(0, 64),
  userText: String(_prep2.userText || '').trim(),
  userName: String(_prep2.firstName || '').trim(),
  userImage: String(_prep2.profilePic || '').trim(),
  assistantText: String(replyText || '').trim(),
  products: (typeof products !== 'undefined' && Array.isArray(products)) ? products : [],
};

// Бүтээгдэхүүнгүй бол зөвхөн текст
if (!showProducts) {
  return [{ json: { psid, replyText, hasCards: false, elements: [], platform, _ingest } }];
}

const NLs = NL;
const clip = function(s,m){ s=String(s||'').split(NLs).join(' ').trim(); while(s.indexOf('  ')!==-1) s=s.split('  ').join(' '); return s.length>m?s.slice(0,m-1).trim()+'…':s; };
const fmt = function(n0){ var n=Math.round(Number(n0)||0),str=String(n),out='',c=0; for(var i=str.length-1;i>=0;i--){out=str[i]+out;c++;if(c%3===0&&i>0)out=','+out;} return out+TUG; };

// Үнэгүй эсэхийг шалгах. ⚠️ Үнэгүй product-д price=compareAtPrice(>0), salePrice=0
// байдаг тул БОДИТ төлөх үнээр (salePrice байвал тэр, эс бол price) шалгана.
const isFreeP = function(p){ var eff = (p.salePrice!=null) ? (Number(p.salePrice)||0) : (Number(p.price)||0); return eff===0; };

// Carousel элемент бэлдэх (FB ба IG хоёуланд — IG ч generic template дэмждэг)
const elements = products.slice(0,10).map(function(p){
  var priceLine= isFreeP(p) ? '🎁 Үнэгүй' : ((p.salePrice!=null)?('💰 '+fmt(p.salePrice)+'  ·  хуучин '+fmt(p.price)):('💰 '+fmt(p.price)));
  var room=79-priceLine.length; var desc=room>12?clip(p.description,room):'';
  var subtitle=desc?clip(priceLine+NLs+desc,80):clip(priceLine,80);
  var el={ title:clip(p.title,80), subtitle:subtitle, default_action:{type:'web_url',url:p.url,webview_height_ratio:'full'}, buttons:[{type:'web_url',url:p.url,title:'Дэлгэрэнгүй үзэх'}] };
  if(p.imageUrl) el.image_url=p.imageUrl;
  return el;
});

// IG-д Send Cards алдвал ашиглах текст fallback (бүтээгдэхүүн жагсаалт)
let cardFallbackText = replyText;
if (platform === 'instagram') {
  let lines = [replyText, ''];
  products.slice(0, 5).forEach(function(p){
    var price = isFreeP(p) ? '🎁 Үнэгүй' : ((p.salePrice != null) ? (fmt(p.salePrice) + ' (хямд)') : fmt(p.price));
    lines.push('🛍️ ' + p.title);
    lines.push('   ' + price);
    if (p.url) lines.push('   🔗 ' + p.url);
    lines.push('');
  });
  cardFallbackText = lines.join(NLs).trim();
  if (cardFallbackText.length > 950) cardFallbackText = cardFallbackText.slice(0, 947) + '...';
}

return [{ json: { psid, replyText, hasCards: elements.length > 0, elements, platform, cardFallbackText, _ingest } }];

const body=$input.first().json.body;
if(!body)return [];
var IGID='17841433844785813';
var PAGEID='1052275041465153';
var out=[];
for(var ei=0;ei<(body.entry||[]).length;ei++){
  var changes=(body.entry[ei].changes)||[];
  for(var ci=0;ci<changes.length;ci++){
    var ch=changes[ci];
    var v=ch.value||{};
    // FB comment (object=page, field=feed)
    if(body.object==='page' && ch.field==='feed'){
      if(v.item!=='comment'||v.verb!=='add')continue;
      var fbCid=v.comment_id; var fbFrom=v.from&&v.from.id;
      if(!fbCid||!fbFrom||fbFrom===PAGEID)continue;
      out.push({json:{platform:'facebook',commentId:fbCid,postId:v.post_id||'',userId:fbFrom}});
    }
    // IG comment (object=instagram, field=comments)
    else if(body.object==='instagram' && ch.field==='comments'){
      var igCid=v.id; var igFrom=v.from&&v.from.id;
      // өөрийн (IG account) сэтгэгдэлд хариулахгүй (давталт)
      if(!igCid||!igFrom||igFrom===IGID)continue;
      var mediaId=(v.media&&v.media.id)||'';
      out.push({json:{platform:'instagram',commentId:igCid,postId:mediaId,igText:String(v.text||''),userId:igFrom}});
    }
  }
}
return out;

var c=$('Parse Comments').first().json;
var post=$input.first().json||{};
var s=String(post.message||post.caption||'');
function findLink(s){
  s=String(s||'');
  var i=s.indexOf('digitalger.mn');
  if(i===-1)return 'https://digitalger.mn';
  var start=i;
  if(s.substr(i-8,8).toLowerCase()==='https://')start=i-8;
  else if(s.substr(i-7,7).toLowerCase()==='http://')start=i-7;
  else if(s.substr(i-4,4).toLowerCase()==='www.')start=i-4;
  var end=start; var stops=[32,10,13,9,41,34,39];
  while(end<s.length && stops.indexOf(s.charCodeAt(end))===-1)end++;
  var url=s.slice(start,end);
  if(url.indexOf('http')!==0)url='https://'+url;
  while(url.length && '.,)'.indexOf(url.charAt(url.length-1))!==-1)url=url.slice(0,-1);
  return url;
}
var link=findLink(s);





// === Private DM (хэрэглэгч рүү Messenger чат) — fromCharCode NL (SyntaxError-гүй) ===
var NL=String.fromCharCode(10);

// === DM карт: линкээс төрөл (product/blog/none) + slug задлах (regex-гүй, indexOf) ===
var linkType='none'; var slug='';
function _slugAfter(s, marker){ var i=s.indexOf(marker); if(i===-1) return ''; var rest=s.slice(i+marker.length); var end=0; var stops=[47,63,35,32,10,13,9]; while(end<rest.length && stops.indexOf(rest.charCodeAt(end))===-1) end++; return rest.slice(0,end); }
var ps=_slugAfter(link,'digitalger.mn/products/');
var bs=_slugAfter(link,'digitalger.mn/blog/');
if(ps){ linkType='product'; slug=ps; }
else if(bs){ linkType='blog'; slug=bs; }
var dmText='Сайн байна уу! Таны сонирхсон бүтээгдэхүүний дэлгэрэнгүйг доорх холбоосоор үзээрэй:'+NL+NL+link+NL+NL+'Асуулт байвал шууд бичээрэй, бид туслахад баяртай байх болно.';
var privCommentId=c.commentId;
var replyText='Танд чатаар мэдээлэл илгээлээ. Дэлгэрэнгүй үзэх бол: '+link;
return [{json:{platform:c.platform,commentId:c.commentId,replyText:replyText,privCommentId:privCommentId,dmText:dmText,link:link,linkType:linkType,slug:slug}}];

var b=$('build reply').first().json;
var meta=$input.first().json||{};
var psid=b.privCommentId;
var dmText=b.dmText;
var linkType=b.linkType; var link=b.link;
// мета амжилттай татагдсан эсэх (title бий)
var ok = meta && meta.title && linkType!=='none';
var body;
if(ok){
  var img = linkType==='product' ? ((meta.images&&meta.images[0]&&meta.images[0].url)||'') : (meta.coverImageUrl||'');
  var title = String(meta.title||'').slice(0,80);
  var sub;
  if(linkType==='product'){
    var pr = meta.salePrice||meta.price||0;
    sub = (pr? (String(pr).replace(/B(?=(d{3})+(?!d))/g,',')+'₮') : '') ;
  } else { sub = String(meta.excerpt||'').slice(0,80); }
  var el={title:title, subtitle:sub||' ', image_url:img, default_action:{type:'web_url',url:link}, buttons:[{type:'web_url',url:link,title:'Дэлгэрэнгүй харах'}]};
  // эхлээд танилцуулга текст, дараа карт — 2 message биш, attachment-д текст багтахгүй тул карт дангаар
  body={recipient:{comment_id:psid},message:{attachment:{type:'template',payload:{template_type:'generic',elements:[el]}}}};
} else {
  // линкгүй эсвэл мета алдаа → зүгээр текст
  body={recipient:{comment_id:psid},message:{text:dmText}};
}
return [{json:{dmBody:JSON.stringify(body),hasCard:ok}}];
